p='src/app/[slug]/wizard.tsx'
s=open(p).read()
s=s.replace('import { useCallback, useEffect, useMemo, useState }','import { useCallback, useEffect, useMemo, useRef, useState }')
old=s[s.index('  const loadSlots = useCallback'):s.index('  useEffect(loadSlots, [loadSlots]);')]
new='''  const slotsKey = service && master ? `${service.id}|${master.id}|${date}` : null;
  const currentKey = useRef<string | null>(null);
  const latestRequest = useRef(0);
  useEffect(() => {
    currentKey.current = slotsKey;
  }, [slotsKey]);

  // A response is applied only if it is the newest request and its selection is still current.
  const loadSlots = useCallback(() => {
    if (!service || !master) return;
    const key = `${service.id}|${master.id}|${date}`;
    const request = ++latestRequest.current;
    const isCurrent = () => request === latestRequest.current && key === currentKey.current;
    fetch(`/api/public/${slug}/slots?serviceId=${service.id}&staffId=${master.id}&date=${date}`)
      .then((r) => r.json())
      .then((d) => {
        if (isCurrent()) setSlots(d.slots ?? []);
      })
      .catch(() => {
        if (isCurrent()) setError("Could not load available times");
      });
  }, [slug, service, master, date]);

'''
s=s.replace(old,new)
open(p,'w').write(s)
